#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// 归并排序统计全部逆序对（k=1）
ll count_all_inv(vector<int>& a) {
    int n = a.size();
    vector<int> tmp(n);
    function<ll(int,int)> dfs = [&](int l, int r) -> ll {
        if (r - l <= 1) return 0;
        int m = (l + r) >> 1;
        ll cnt = dfs(l, m) + dfs(m, r);
        int i = l, j = m, p = l;
        while (i < m || j < r) {
            if (j == r || (i < m && a[i] <= a[j]))
                tmp[p++] = a[i++];
            else {
                cnt += (m - i);
                tmp[p++] = a[j++];
            }
        }
        for (int k = l; k < r; ++k) a[k] = tmp[k];
        return cnt;
    };
    return dfs(0, n);
}

// 树状数组
struct BIT {
    int n;
    vector<int> t;
    BIT(int _n) : n(_n), t(_n + 1, 0) {}
    void update(int i, int v = 1) {
        for (; i <= n; i += i & -i) t[i] += v;
    }
    int query(int i) {
        int s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    if (k >= 3) {
        cout << 0 << '\n';
        return 0;
    }

    if (k == 1) {
        cout << count_all_inv(a) << '\n';
    } else { // k == 2
        BIT bit_even(n), bit_odd(n);
        for (int x : a) {
            if (x & 1)
                bit_odd.update(x, 1);
            else
                bit_even.update(x, 1);
        }
        ll ans = 0;
        for (int x : a) {
            if (x & 1) {
                bit_odd.update(x, -1);
                ans += bit_even.query(x - 1);
            } else {
                bit_even.update(x, -1);
                ans += bit_odd.query(x - 1);
            }
        }
        cout << ans << '\n';
    }
    return 0;
}
